// FUNCTION: BFME2 0x0027D40B size=60 name=?isBridgeRepaired@TerrainLogic@@QAE_NPBVObject@@@Z evidence=N:ledger tier=A
Bool TerrainLogic::isBridgeRepaired(const Object *bridge)
{
	if (!bridge)
		return false;
	ObjectID id = bridge->getID();
	Bridge *pBridge = getFirstBridge();
	while (pBridge)
	{
		const BridgeInfo *info = pBridge->peekBridgeInfo();
		if (info->bridgeObjectID == id)
		{
			if (info->damageStateChanged)
			{
				if (info->curDamageState != BODY_RUBBLE)
				{
					return true;
				}
			}
			return false;
		}
		pBridge = pBridge->getNext();
	}
	return false;
}

// FUNCTION: BFME2 0x0027D447 size=60 name=?isBridgeBroken@TerrainLogic@@QAE_NPBVObject@@@Z evidence=N:ledger tier=A
Bool TerrainLogic::isBridgeBroken(const Object *bridge)
{
	if (!bridge)
		return false;
	ObjectID id = bridge->getID();
	Bridge *pBridge = getFirstBridge();
	while (pBridge)
	{
		const BridgeInfo *info = pBridge->peekBridgeInfo();
		if (info->bridgeObjectID == id)
		{
			if (info->damageStateChanged)
			{
				if (info->curDamageState == BODY_RUBBLE)
				{
					return true;
				}
			}
			return false;
		}
		pBridge = pBridge->getNext();
	}
	return false;
}

