Real TerrainLogic::getWaterDepth(Real x, Real y)
{
	Real waterZ = 0.0f;
	Real terrainZ = 0.0f;
	if (!isUnderwater(x, y, &waterZ, &terrainZ, NULL))
		return 0.0f;
	return waterZ - terrainZ;
}

