// FUNCTION: BFME2 0x0027EDBC size=241 name=?createTower@Bridge@@QAEPAVObject@@PAVCoord3D@@W4BridgeTowerType@@PBVThingTemplate@@PAV2@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A

// FUNCTION: BFME2 0x0027EEAD size=348 name=?isPointOnBridge@Bridge@@QAE_NPBVCoord3D@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
Bool Bridge::isPointOnBridge(const Coord3D *pLoc)
{
	if (pLoc->x < m_boundsLoX) return false;
	if (pLoc->x > m_boundsHiX) return false;
	if (pLoc->y < m_boundsLoY) return false;
	if (pLoc->y > m_boundsHiY) return false;

	if (m_polygonTrigger)
	{
		ICoord3D iPos;
		iPos.x = (Int)pLoc->x;
		iPos.y = (Int)pLoc->y;
		iPos.z = (Int)pLoc->z;
		return m_polygonTrigger->pointInTrigger(iPos);
	}

	{
		Vector3 testPt(pLoc->x, pLoc->y, pLoc->z);
		Vector3 left1(m_bridgeInfo.fromLeft.x, m_bridgeInfo.fromLeft.y, m_bridgeInfo.fromLeft.z);
		Vector3 right1(m_bridgeInfo.fromRight.x, m_bridgeInfo.fromRight.y, m_bridgeInfo.fromRight.z);
		Vector3 left2(m_bridgeInfo.toLeft.x, m_bridgeInfo.toLeft.y, m_bridgeInfo.toLeft.z);
		Vector3 right2(m_bridgeInfo.toRight.x, m_bridgeInfo.toRight.y, m_bridgeInfo.toRight.z);
		unsigned char flags;
		if (Point_In_Triangle_2D(left1, right1, left2, testPt, 0, 1, flags))
			return true;
		if (Point_In_Triangle_2D(right1, left2, right2, testPt, 0, 1, flags))
			return true;
	}
	return false;
}

// FUNCTION: BFME2 0x0027F009 size=150 name=?addWaypointLink@TerrainLogic@@IAEXHH@Z evidence=N:ledger tier=A
void TerrainLogic::addWaypointLink(Int id1, Int id2)
{
	Waypoint *pWay1 = NULL;
	Waypoint *pWay2 = NULL;
	Waypoint *pWay;
	for (pWay = getFirstWaypoint(); pWay; pWay = pWay->m_next)
	{
		if (pWay->getID() == id1)
			pWay1 = pWay;
		if (pWay->getID() == id2)
			pWay2 = pWay;
	}
	if (pWay1 == NULL || pWay2 == NULL)
		return;
	if (pWay1 == pWay2)
		return;

	Int i;
	for (i = 0; i < pWay1->m_numLinks; i++)
	{
		if (pWay1->getLink(i) == pWay2)
			return;
	}
	pWay1->addLink(pWay2);

	if (pWay1->m_biDirectional)
	{
		for (i = 0; i < pWay2->m_numLinks; i++)
		{
			if (pWay2->getLink(i) == pWay1)
				return;
		}
		pWay2->addLink(pWay1);
	}
}

