Bridge *TerrainLogic::findBridgeAt(const Coord3D *pLoc) const
{
	Bridge *pBridge = getFirstBridge();
	while (pBridge)
	{
		if (pBridge->isPointOnBridge(pLoc))
		{
			return pBridge;
		}
		pBridge = pBridge->getNext();
	}
	return NULL;
}

// FUNCTION: BFME2 0x0027F337 size=76 name=?findBridgeLayerAt@TerrainLogic@@UBEPAVBridge@@PBVCoord3D@@W4PathfindLayerEnum@@_N@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
Bridge *TerrainLogic::findBridgeLayerAt(const Coord3D *pLoc, PathfindLayerEnum layer, Bool clip) const
{
	if (layer == LAYER_GROUND || (Int)layer > 15)
		return NULL;

	Bridge *pBridge = getFirstBridge();
	while (pBridge)
	{
		if (pBridge->getLayer() == layer && (!clip || pBridge->isPointOnBridge(pLoc)))
		{
			return pBridge;
		}
		pBridge = pBridge->getNext();
	}
	return NULL;
}

