// FUNCTION: BFME2 0x0027FFF3 size=60 name=?parseWaypointData@TerrainLogic@@IAE_NAAVDataChunkInput@@PAUDataChunkInfo@@PAX@Z evidence=N:ledger tier=A
Bool TerrainLogic::parseWaypointData(DataChunkInput &file, DataChunkInfo *info, void *userData)
{
	Int count = file.readInt();
	while (count > 0)
	{
		count--;
		Int waypointID1 = file.readInt();
		Int waypointID2 = file.readInt();
		addWaypointLink(waypointID1, waypointID2);
	}
	return true;
}

