// FUNCTION: BFME2 0x002812BF size=299 name=?getClosestWaypointOnPath@TerrainLogic@@UAEPAVWaypoint@@PBVCoord3D@@ABVAsciiString@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
Waypoint *TerrainLogic::getClosestWaypointOnPath(const Coord3D *pos, const AsciiString &label)
{
	if (pos == NULL)
		return getWaypointByPath(label);

	Real distSqr = 0;
	Waypoint *pClosestWay = NULL;
	if (label.isEmpty())
	{
		return NULL;
	}

	for (Waypoint *way = TheWaypointListHead; way; way = way->m_next)
	{
		Bool match = false;
		if (label.compareNoCase(way->getPathLabel1()) == 0) match = true;
		if (label.compareNoCase(way->getPathLabel2()) == 0) match = true;
		if (label.compareNoCase(way->getPathLabel3()) == 0) match = true;
		if (match)
		{
			Coord3D curPos = way->m_location;
			Real newDistSqr = (curPos.x - pos->x) * (curPos.x - pos->x) + (curPos.y - pos->y) * (curPos.y - pos->y);
			if (pClosestWay == NULL)
			{
				pClosestWay = way;
				distSqr = newDistSqr;
			}
			else if (newDistSqr < distSqr)
			{
				pClosestWay = way;
				distSqr = newDistSqr;
			}
		}
	}

	return pClosestWay;
}

// FUNCTION: BFME2 0x002813EA size=261 name=?getWaypointByPath@TerrainLogic@@UAEPAVWaypoint@@ABVAsciiString@@@Z evidence=N:ledger tier=A
Waypoint *TerrainLogic::getWaypointByPath(const AsciiString &label)
{
	if (label.isEmpty())
		return NULL;

	for (Waypoint *way = TheWaypointListHead; way; way = way->m_next)
	{
		Bool match = false;
		if (label.compareNoCase(way->getPathLabel1()) == 0 ||
			label.compareNoCase(way->getPathLabel2()) == 0 ||
			label.compareNoCase(way->getPathLabel3()) == 0)
			match = true;
		if (match)
		{
			// the path's first waypoint is the one nothing links to
			while (way->m_owner)
				way = way->m_owner;
			return way;
		}
	}
	return NULL;
}

