// FUNCTION: BFME2 0x00281D4C size=59 name=?getWaypointByName@TerrainLogic@@UAEPAVWaypoint@@ABVAsciiString@@@Z evidence=N:ledger tier=A
Waypoint *TerrainLogic::getWaypointByName(const AsciiString &name)
{
	if (name.isEmpty())
		return NULL;

	for (Waypoint *way = TheWaypointListHead; way; way = way->m_next)
		if (way->m_name == name)
			return way;

	return NULL;
}

// FUNCTION: BFME2 0x00281D92 size=181 name=?isPurposeOfPath@TerrainLogic@@UAE_NPAVWaypoint@@ABVAsciiString@@@Z evidence=N:ledger tier=A
Bool TerrainLogic::isPurposeOfPath(Waypoint *pWay, const AsciiString &label)
{
	if (label.isEmpty() || pWay == NULL)
	{
		return false;
	}

	Bool match = false;
	if (label == pWay->getPathLabel1()) match = true;
	if (label == pWay->getPathLabel2()) match = true;
	if (label == pWay->getPathLabel3()) match = true;

	return match;
}

